"""GitHub API 客户端：自动带 Token、区分错误类型、限流退避一次。"""

import os
import time

import httpx

GITHUB_API = "https://api.github.com"


class GitHubClient:
    """封装 GitHub REST API 调用，错误以结构化 dict 返回，不静默吞掉。"""

    def __init__(self, token: str | None = None, base_url: str = GITHUB_API):
        self.token = token or os.getenv("GITHUB_TOKEN", "")
        self.base_url = base_url
        self.headers = {
            "Accept": "application/vnd.github+json",
            "User-Agent": "github-project-agent",
        }
        if self.token:
            self.headers["Authorization"] = f"Bearer {self.token}"
        self.client = httpx.Client(base_url=self.base_url, headers=self.headers, timeout=20)
        self.last_rate = {}

    def _record_rate(self, resp: httpx.Response) -> None:
        self.last_rate = {
            "limit": resp.headers.get("X-RateLimit-Limit"),
            "remaining": resp.headers.get("X-RateLimit-Remaining"),
            "reset": resp.headers.get("X-RateLimit-Reset"),
        }

    def get(self, path: str, params: dict | None = None, _retried: bool = False) -> dict:
        if not self.token:
            return {
                "ok": False,
                "status": 401,
                "error_type": "missing_token",
                "message": "未配置 GITHUB_TOKEN，请在 .env 中设置后重试。",
            }

        resp = self.client.get(path, params=params)
        self._record_rate(resp)

        if resp.status_code == 401:
            return {
                "ok": False,
                "status": 401,
                "error_type": "auth",
                "message": "Token 无效或已过期，请重新生成。",
            }

        if resp.status_code == 404:
            return {
                "ok": False,
                "status": 404,
                "error_type": "not_found",
                "message": "资源不存在或当前 Token 无权访问。",
            }

        if resp.status_code == 403 or resp.status_code == 429:
            retry_after = resp.headers.get("Retry-After")
            remaining = resp.headers.get("X-RateLimit-Remaining")
            is_rate_limited = resp.status_code == 429 or remaining == "0" or retry_after is not None
            if is_rate_limited and not _retried:
                wait = int(retry_after) if retry_after and retry_after.isdigit() else 60
                time.sleep(wait)
                return self.get(path, params=params, _retried=True)
            return {
                "ok": False,
                "status": resp.status_code,
                "error_type": "rate_limit" if is_rate_limited else "forbidden",
                "message": "触发 GitHub 限流，已退避重试一次仍失败。" if is_rate_limited else "当前 Token 权限不足。",
                "retry_after": retry_after,
            }

        if resp.status_code >= 400:
            return {
                "ok": False,
                "status": resp.status_code,
                "error_type": "http_error",
                "message": f"GitHub 返回错误：{resp.status_code}",
            }

        return {
            "ok": True,
            "status": resp.status_code,
            "data": resp.json(),
            "rate": self.last_rate,
        }

"""工具层：Agent 可以调用的函数与对应的 JSON Schema。"""

import base64
from datetime import datetime, timedelta, timezone as dt_timezone
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from github_client import GitHubClient

_FALLBACK_OFFSETS = {
    "Asia/Shanghai": 8,
    "UTC": 0,
}


def get_current_time(timezone: str = "Asia/Shanghai") -> str:
    """返回指定 IANA 时区的当前时间，格式：YYYY-MM-DD HH:MM:SS 时区名。"""
    try:
        tz = ZoneInfo(timezone)
    except ZoneInfoNotFoundError:
        if timezone not in _FALLBACK_OFFSETS:
            raise ValueError(f"未知时区：{timezone}")
        tz = dt_timezone(timedelta(hours=_FALLBACK_OFFSETS[timezone]), timezone)
    return datetime.now(tz).strftime("%Y-%m-%d %H:%M:%S %Z")


_client: GitHubClient | None = None


def _get_client() -> GitHubClient:
    global _client
    if _client is None:
        _client = GitHubClient()
    return _client


MAX_FILE_BYTES = 100_000
MAX_TREE_ENTRIES = 300


def get_repo_info(owner: str, repo: str) -> dict:
    """返回仓库元数据：描述、默认分支、语言、star、更新时间等。"""
    result = _get_client().get(f"/repos/{owner}/{repo}")
    if not result.get("ok"):
        return result
    data = result["data"]
    return {
        "ok": True,
        "full_name": data.get("full_name"),
        "description": data.get("description"),
        "default_branch": data.get("default_branch"),
        "language": data.get("language"),
        "stars": data.get("stargazers_count"),
        "forks": data.get("forks_count"),
        "open_issues": data.get("open_issues_count"),
        "updated_at": data.get("updated_at"),
        "html_url": data.get("html_url"),
    }


def get_file_tree(owner: str, repo: str, branch: str = "main") -> dict:
    """返回分支的文件树（仅文件路径），条目过多时截断并标记 truncated。"""
    result = _get_client().get(f"/repos/{owner}/{repo}/git/trees/{branch}", params={"recursive": "1"})
    if not result.get("ok"):
        return result
    data = result["data"]
    files = [node["path"] for node in data.get("tree", []) if node.get("type") == "blob"]
    truncated = len(files) > MAX_TREE_ENTRIES
    return {
        "ok": True,
        "branch": branch,
        "count": len(files),
        "truncated": truncated,
        "files": files[:MAX_TREE_ENTRIES],
    }


def get_file_content(owner: str, repo: str, path: str, ref: str = "main",
                     max_bytes: int = MAX_FILE_BYTES) -> dict:
    """读取单个文件内容；超过 max_bytes 只返回元数据，避免把上下文撑爆。"""
    result = _get_client().get(f"/repos/{owner}/{repo}/contents/{path}", params={"ref": ref})
    if not result.get("ok"):
        return result
    data = result["data"]
    size = data.get("size", 0)
    if size > max_bytes or data.get("encoding") == "none":
        return {
            "ok": True,
            "path": data.get("path"),
            "size": size,
            "truncated": True,
            "message": f"文件 {size} 字节，超过上限 {max_bytes}，仅返回元数据，请改用局部路径或缩小范围。",
        }
    content = base64.b64decode(data.get("content", "")).decode("utf-8", errors="replace")
    return {
        "ok": True,
        "path": data.get("path"),
        "size": size,
        "truncated": False,
        "content": content,
    }


TOOL_FUNCTIONS = {
    "get_current_time": get_current_time,
    "get_repo_info": get_repo_info,
